from docx import Document
from lxml import etree

doc = Document('offer_letter_template.docx')

# The table seems to have only 1 column, but the XML might have nested tables or sub-paragraphs
# Let me look at the full XML of each table row
for ti, table in enumerate(doc.tables):
    for ri, row in enumerate(table.rows):
        for ci, cell in enumerate(row.cells):
            all_paras = cell.paragraphs
            print(f"Table {ti}, Row {ri}, Cell {ci}: {len(all_paras)} paragraphs")
            for pi, p in enumerate(all_paras):
                runs = [(r.text, r.bold) for r in p.runs]
                print(f"  P{pi}: {runs}")

# Let's also check if there are nested tables
body = doc.element.body
ns = {'w': 'http://schemas.openxmlformats.org/wordprocessingml/2006/main'}
tables = body.findall('.//w:tbl', ns)
print(f"\nTotal tables found in XML: {len(tables)}")
for ti, tbl in enumerate(tables):
    rows = tbl.findall('w:tr', ns)
    print(f"Table {ti}: {len(rows)} rows")
    for ri, row in enumerate(rows):
        cells = row.findall('w:tc', ns)
        print(f"  Row {ri}: {len(cells)} cells")
        for ci, cell in enumerate(cells):
            paras = cell.findall('w:p', ns)
            for pi, p in enumerate(paras):
                text_nodes = p.findall('.//w:t', ns)
                text = ''.join(t.text or '' for t in text_nodes)
                if text.strip():
                    print(f"    Cell {ci} P{pi}: \"{text}\"")
