from docx import Document
from docx.text.paragraph import Paragraph
from docx.table import Table

doc = Document('/root/offer_letter_filled.docx')

print("=== BODY PARAGRAPHS ===")
for i, p in enumerate(doc.paragraphs):
    if p.text.strip():
        print(f"P{i}: {p.text}")

print("\n=== ALL TABLES (via XML) ===")
from lxml import etree
ns = {'w': 'http://schemas.openxmlformats.org/wordprocessingml/2006/main'}
all_tbls = doc.element.body.findall('.//w:tbl', ns)
for ti, tbl_elem in enumerate(all_tbls):
    table = Table(tbl_elem, doc)
    print(f"\n--- Table {ti} ---")
    for ri, row in enumerate(table.rows):
        for ci, cell in enumerate(row.cells):
            for pi, p in enumerate(cell.paragraphs):
                if p.text.strip():
                    print(f"  R{ri}C{ci}: {p.text}")

# Check for any remaining placeholders
print("\n=== CHECKING FOR REMAINING PLACEHOLDERS ===")
ns_p = '{http://schemas.openxmlformats.org/wordprocessingml/2006/main}p'
found = False
for p_elem in doc.element.body.iter(ns_p):
    para = Paragraph(p_elem, doc)
    text = para.text
    if '{{' in text and '}}' in text:
        print(f"REMAINING: {text}")
        found = True
if not found:
    print("None found - all placeholders replaced successfully!")
